import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"卷六（杂卦）","description":"伊川易传 - 卷六（杂卦）","frontmatter":{"title":"卷六（杂卦）","description":"伊川易传 - 卷六（杂卦）"},"headers":[],"relativePath":"zh/classics/yichuan/007.md","filePath":"zh/classics/yichuan/007.md"}'),s={name:"zh/classics/yichuan/007.md"};function i(c,a,n,l,o,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="卷六-杂卦" tabindex="-1">卷六（杂卦） <a class="header-anchor" href="#卷六-杂卦" aria-label="Permalink to “卷六（杂卦）”">​</a></h1><p>第一段</p><p>乾刚坤柔，比乐师忧(1)。临观之义，或与或求。屯见而不失其居，蒙杂而著(2)。震，起也；艮，止也。损益，盛衰之始也。大畜，时也；无妄，灾也(3)。萃聚而升不来也，谦轻而豫怠也。噬嗑，食也；贲，无色也。兑见而巽伏也(4)。随，无故也；蛊，则饬也。剥，烂也；复，反也。晋，昼也；明夷，诛也(5)。井通而困相遇也。咸，速也；恒，久也。涣，离也；节，止也。解，缓也；蹇，难也。睽，外也；家人，内也。否泰，反其类也(6)。大壮则止，遯则退也。大有，众也；同人，亲也。革，去故也；鼎，取新也(7)。小过，过也；中孚，信也。丰，多故也；亲寡，旅也。离上而坎下也⑧。小畜，寡也；履，不处也。需，不进也；讼，不亲也。大过，颠也。姤，遇也，柔遇刚也。渐，女归待男行也(9)。颐，养正也，即济，定也。归妹，女之终也。未济，男之穷也。夬，决也。刚决柔也。君子道长，小人道忧也。(10)</p><h3 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to “注释”">​</a></h3><p>①乾刚：《乾》卦六爻由纯阳组成，故曰乾刚。坤柔：《坤》卦六爻由纯阴组成，故曰坤柔。比乐：《比》有亲辅之义，故乐。师忧：《师》主军旅，动从行险，故忧。</p><p>②或与或求：或者为施予或者为营求。与，施予；求：营求。《临》二阳在四阴之下，有在上而临下之义，故曰“与”。《观》二阳在四阴之上，“大观在上”有下以仰观上之义，故曰“求”。屯见：《屯》为“物之始生”故曰“见”。见，现。不失其居：指各居其所。《屯》二阳皆当位，故曰“不失其居”。蒙杂：《蒙》二阳失位，阴阳杂居。“屯见而不失其居，蒙杂而著”当为《杂卦》作者以当时传授的象义解《屯》《蒙》二卦。“屯见”、“蒙杂”以及“居”、“著”究竟确义为何，先儒虽有种种解说，恐皆未得实。笔者在此虽参照先儒之说解之，但仍觉不妥，故言明以待来者。</p><p>③盛衰之始：《损》＄为减损《泰》＄下而增益其上，即《彖》所谓“损下益上”，故为衰之始。泰为盛。《益》＄为减损《否》＄上增益其下，即《彖》所谓“损上益下”，故为盛之始。否为衰。时：待时。古“时”、“待”通。王引之云：“家大人（王念孙）</p><p>第三段</p><p>曰：‘时：当读为待，经言：归妹愆期，迟归有时。故《传》申之曰：愆期之志，有待而行也’”大畜有畜养其德之义，故曰“时”。灾：《无妄》为大旱卦。《集解》引京氏注《无妄》卦：“大旱之年，万物皆死，无所复生。”故《彖》称：“天命不祐。”故曰“灾”。</p><p>④不平：即《序卦》所谓“聚而上者谓之升”。《萃》卦三阴聚于下，《升》卦三阴在于上，故曰“不来”。到内曰来，到外称往。不来，指不在内而在外。谦轻：《谦》卦有谦退之义，故曰轻。豫怠：《豫》卦有娱乐之义，故怠。怠，和乐。一本作怡，怠、怡二字通。食：吃。噬嗑是指口中有物，故曰食。无色：即白色。《贲》离日在艮山下而无光，故曰“无色”。兑见而巽状：兑阴在上故曰“见”，巽阴在下故曰“伏”。</p><p>⑤无故：无事。《随《卦》有随时而安之义，即《象传》所谓“君子以向晦入宴息”。故为“无故”。饬：一本作“饰”，训为整治，《蛊》为有事之卦，《序卦》“蛊者，事也”，有事则需要修整，故曰“饬”。烂：熟烂。《剥》一阳被五阴剥落，象果熟烂被剥落一样，故曰“烂”。反：通“返”。《复》一阳复返于初，故曰“反”。昼：《晋》卦下坤为地，上离为日，日出地上，故为“昼”。诛：伤。《明夷》下离为日，上坤为地，日入地中，其光明受伤，故曰“诛”。</p><p>⑥井通而困相遇：井水本在下，而《井》卦水在木上，以承水而上，“井养而不穷”，“往来不穷”故谓之“通”。而《困》相反，水在泽下，泽上无水而乾涸，故曰“不通”，不通即是阻隔。速：神速。《咸》卦有感之义。“二气感应”，感而遂通，不行而至，故称“速”。离：《涣》感之义。“二气感应”，感而遂通，不行而至，故称“速”。离：《涣》卦有披离解散之象，故曰“离”。止：《节》卦有节止之义，故曰“止”。缓：《解》卦有解除、缓解之义，故曰“缓”。难：《蹇》卦坎险在前，艮见险而止于内，有难之义。外：《序卦》：“睽者，乖也。”《广雅·释诂》：“乖，离也。”有离家之义。又《睽》离女在外卦，有女离家在外之义，故曰“外”。内：《家人》离女在内卦，女在家内故曰“内”。反其类：《泰》《否》卦画相反，《否》反成《泰》，《泰》反成《否》，其事类相反。</p><p>⑦大壮则止：《大壮》四阳进消阴，阳长过半将止，故“止”。遯则退：《遯》阴进消阳，阳势消退，故“遯则退”。众：《大有》六五之柔得尊位，上下五阳皆应之，故曰众。亲：《同人》六二居中得位，众阳皆亲附，如《序卦》所称：“与人同者，物必归焉。”故曰“亲”。革去故：《革》卦有改革、更新之义，故曰“去故”。故，指旧有。鼎取新：《鼎》卦离火在上，巽木生之，有鼎烹饪之象，鼎烹饪待熟而取新。</p><p>⑧过：《小过》阴盛过阳，故为“过”。过，经过。《序卦》：“有其信者必行之，故受之以小过。”信：《中孚》取信发于中，孚有信之义。故曰“信”。多故；《丰》乃日蚀之卦，古人多以日蚀为不祥，故曰“多故”。故，事。亲寡：旅无所容身，故“亲寡”。明何楷《古周易订诂》引或曰：“‘亲寡旅’当作‘旅寡亲’，于韵亦协。”清崔述等从之，并作了详细辩证，他说：“此传之文，皆先举卦名，而后释其义，不容此句独先释之，而后倒之卦之后，一也。上文云：‘丰多故’正与此文之‘旅寡亲’两两相对。而‘亲寡’亦不如‘寡亲’之文义明顺，二也。《大有》以下诸卦，皆真文韵，此句‘亲’字正与上文‘亲’、‘新’、‘信’三字相叶，三也。”（见《易卦图说》）我们认为此考极确，故当改“亲寡旅也”为“旅寡新也”。离上而坎下：离为火而炎上，坎为水而润下。</p><p>⑨寡：《小畜》一阴畜五阳，阳众阴寡，故曰“寡”。不处：不停止。履有践履之义，且《履》卦阳爻皆以不处其位为吉，故曰“不处”。不进：《需》上坎为险，险在前，而待时，《需·彖》：“需，须也。”须为待，故“不进”。不亲：《讼》卦上乾为天，下坎为水，天水相违行，故“不亲”。颠：本义又指头顶引申为颠覆。《大过》下巽为木，上兑为泽，木顶被泽水淹没，故曰：“颠”。柔遇刚；《姤》卦一阴在下而上与五阳相遇，阴为柔，阳为刚。女归待男行：指女子出嫁等待男子迎亲。《渐》卦下艮为少男。上巽为长女，故有长女归待少男行之义。</p><p>⑩养正：《颐》下震为动，上艮为止，上静下动，人口吃物之象，故曰养正，如《彖》所言：“颐‘贞吉’，养正则吉也。”定：成。《既济》六爻阴居阴位，阳居阳位，阴阳定位，故曰“定”。终：归宿。《归妹》上震为长男，为动，下兑为少女，为说，“说以动”，少女嫁长男之象，女子出嫁为“终”。男之穷：《未济》三阳失正，阳穷极于上，故曰“男之穷”，阳为男。刚决柔：《夬》卦＄五阳盛长，决去一阴，君子道长，小人道忧：《夬》卦阳刚盛长，阴柔消退即将被决去，阳象“君子”，阴象“小人”，故曰“君子道长，小人道忧”。</p><p>《杂卦》虽不依六十四卦之顺序，但两两为对解卦。前五十六卦皆然，独后八卦错乱。汉儒虞翻、晋儒乾宝皆认为此为《杂卦》作者独心匠运、巧妙安排，故虞翻以互体释之。以“喻武王伐纣”。乾宝以变通释之，“以示来圣后王，明道非常道，事非常事也”。然汉郑玄首先提出怀疑：“自此以下，卦意不协，以错乱失正。”（见孙氏《周易》集解）</p><h3 id="第四段" tabindex="-1">第四段 <a class="header-anchor" href="#第四段" aria-label="Permalink to “第四段”">​</a></h3><p>但他“弗敢改耳。宋人苏轼、朱震、蔡渊等人加以改定，元吴澄、明何楷等从之。改定后的次序有两种：</p><p>颐，养正也；大过，颠也。姤，遇也，柔遇刚也；夬，决也，刚决柔也。君子道长，小人道忧也。渐，女归待男行也；归妹，女之终也。既济，定也；未济，男之穷也。此以苏轼为代表。</p><p>大过，颠也；颐，养正也。既济，定也；未济，男之穷也。归妹，女之终也；渐，女归待男行也。姤，遇也，柔遇刚也；夬，决也，刚决柔也，君子道长，小人道忧也。以蔡渊为代表。案音韵学，当以后者胜。</p>',21)])])}const m=p(s,[["render",i]]);export{d as __pageData,m as default};
